             INSERT INTO moz_places VALUES (1, 'https://history.invalid', 0), (2, 'https://bookmark.invalid', 1), (3, 'https://download.invalid', 0);
             INSERT INTO moz_historyvisits VALUES (1, 1, 1, 1), (2, 2, 1, 1), (3, 3, 7, 1);
