fn directories_with_leaf_names(path: &Path, leaf_names: &[&str]) -> Vec<PathBuf> {
    fn collect(path: &Path, leaf_names: &[&str], directories: &mut Vec<PathBuf>) {
        let metadata =
            fs::symlink_metadata(path).expect("the WPS profile path must remain readable");
        assert!(
            !metadata.file_type().is_symlink(),
            "the WPS profile fixture must not cross a symbolic link"
        );
        if !metadata.is_dir() {
            return;
        }
        if path.file_name().is_some_and(|name| {
            leaf_names
                .iter()
                .any(|leaf| name.eq_ignore_ascii_case(leaf))
        }) {
            directories.push(path.to_path_buf());
            return;
        }
        let mut children = fs::read_dir(path)
            .expect("the WPS profile directory must remain readable")
            .map(|entry| entry.expect("the directory entry must be readable").path())
            .filter(|child| child.is_dir())
            .collect::<Vec<_>>();
        children.sort();
        for child in children {
            collect(&child, leaf_names, directories);
        }
    }

    let mut directories = Vec::new();
    collect(path, leaf_names, &mut directories);
    directories.sort();
    directories
}

fn digest_tree_excluding_segments(path: &Path, excluded_segments: &[&str]) -> String {
    fn collect_files(path: &Path, excluded_segments: &[&str], files: &mut Vec<PathBuf>) {
        let metadata = fs::symlink_metadata(path)
            .expect("the preserved WPS application state must remain readable");
        assert!(
            !metadata.file_type().is_symlink(),
            "the preserved WPS fixture must not contain links"
        );
        if metadata.is_file() {
            files.push(path.to_path_buf());
            return;
        }
        let mut children = fs::read_dir(path)
            .expect("the preserved WPS directory must remain readable")
            .map(|entry| entry.expect("the directory entry must be readable").path())
            .filter(|child| {
                !child.file_name().is_some_and(|name| {
                    excluded_segments
                        .iter()
                        .any(|segment| name.eq_ignore_ascii_case(segment))
                })
            })
            .collect::<Vec<_>>();
        children.sort();
        for child in children {
            collect_files(&child, excluded_segments, files);
        }
    }

    let mut files = Vec::new();
    collect_files(path, excluded_segments, &mut files);
    let mut hasher = Sha256::new();
    for file in files {
        let relative = file
            .strip_prefix(path)
            .unwrap_or(file.as_path())
            .to_string_lossy();
        hasher.update(relative.as_bytes());
        hasher.update(fs::read(file).expect("the preserved WPS file must remain readable"));
    }
    hasher.finalize().iter().map(|byte| format!("{byte:02x}")).collect::<String>()
}

fn digest_tree(path: &Path) -> String {
    fn collect_files(path: &Path, files: &mut Vec<PathBuf>) {
        let metadata =
            fs::symlink_metadata(path).expect("the preserved Signal path must remain readable");
        assert!(
            !metadata.file_type().is_symlink(),
            "the preserved Signal fixture must not contain links"
        );
        if metadata.is_file() {
            files.push(path.to_path_buf());
            return;
        }
        let mut children = fs::read_dir(path)
            .expect("the preserved Signal directory must remain readable")
            .map(|entry| entry.expect("the directory entry must be readable").path())
            .collect::<Vec<_>>();
        children.sort();
        for child in children {
            collect_files(&child, files);
        }
    }

    let mut files = Vec::new();
    collect_files(path, &mut files);
    let mut hasher = Sha256::new();
    for file in files {
        let relative = file
            .strip_prefix(path)
            .unwrap_or(file.as_path())
            .to_string_lossy();
        hasher.update(relative.as_bytes());
        hasher.update(fs::read(file).expect("the preserved Signal file must remain readable"));
    }
    hasher.finalize().iter().map(|byte| format!("{byte:02x}")).collect::<String>()
}

import { describe, expect, it } from 'vitest';
import type { AnalysisDeleteResult, AnalysisResult } from '@/lib/models/storage/analysis';
import { key, syncAfterDelete } from '@/lib/utils/storage/analysis-cache';

function snapshot(root: string, scanId: number, totalBytes = 64): AnalysisResult {
  return { scanId, root, scannedAtMs: 1, totalBytes, skippedCount: 0, truncated: false, entries: [] };
}

describe('analysis cache deletion synchronization', () => {
  it.each([
    ['/fixture', '/fixture/child', '/sibling'],
    ['C:\\Fixture', 'c:/fixture/Child', 'C:\\Sibling'],
    ['\\\\server\\share\\Fixture', '\\\\server\\share\\Fixture\\Child', '\\\\server\\share\\Sibling'],
  ])('uses scan authority for %s without expiring a transferred sibling', (root, child, sibling) => {
    const source = snapshot(root, 7);
    const outdatedChild = snapshot(child, 8);
    const sharedSibling = snapshot(sibling, 9, 0);
    const unrelated = snapshot('/unrelated', 10);
    const cache = Object.fromEntries(
      [source, outdatedChild, sharedSibling, unrelated].map(row => [key(row.root), row])
    );
    const updatedSource = { ...source, totalBytes: 0 };
    const updatedSibling = { ...sharedSibling, totalBytes: 64 };
    const response: AnalysisDeleteResult = {
      schemaVersion: 1,
      requiresRescan: false,
      removedPath: `${root}/deleted.bin`,
      releasedBytes: 64,
      removedFileCount: 1,
      updatedResults: [updatedSource, updatedSibling],
      invalidatedScanIds: [8],
    };
    const synchronized = syncAfterDelete(cache, Object.keys(cache), response, 80).cache;
    expect(synchronized[key(root)]).toBe(updatedSource);
    expect(synchronized[key(child)]).toBeUndefined();
    expect(synchronized[key(sibling)]).toBe(updatedSibling);
    expect(synchronized['/unrelated']).toBe(unrelated);
    expect(cache[key(root)]).toBe(source);
    expect(cache[key(child)]).toBe(outdatedChild);
    expect(sharedSibling.totalBytes).toBe(0);
  });

  it('replaces a Windows root under the same normalized key', () => {
    const previous = snapshot('C:\\Fixture', 7);
    const updated = snapshot('c:/FIXTURE/', 9, 20);
    const synchronized = syncAfterDelete(
      { [key(previous.root)]: previous },
      [key(previous.root)],
      {
        schemaVersion: 1,
        requiresRescan: false,
        removedPath: 'C:\\Fixture\\item',
        releasedBytes: 44,
        removedFileCount: 1,
        updatedResults: [updated],
        invalidatedScanIds: [7],
      },
      80
    ).cache;
    expect(Object.keys(synchronized)).toEqual([key(previous.root)]);
    expect(synchronized[key(previous.root)]).toBe(updated);
  });
});

